w+1],em=fabs(m[i]-gm),es=fabs(s[i]-gs);maxerr=fmax(maxerr,fmax(em,es));ok&=std::isfinite(m[i])&&std::isfinite(s[i])&&em<=5e-4+2e-6*fabs(gm)&&es<=1e-3+2e-6*fabs(gs);}}out.insert(out.end(),m.begin(),m.end());out.insert(out.end(),s.begin(),s.end());out.insert(out.end(),x.begin(),x.end());}double sum=0;for(double t:times)sum+=t;std::string path="/tmp/rowwise_"+std::to_string(getpid())+"_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)prefix.data(),prefix.size()*8);f.write((char*)out.data(),out.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"max_abs_error\":%.12g,\"max_rel_error\":null,\"jit_excluded\":true,\"timing_region\":\"sum_eight_Welford_launch_batches_plus_device_completion_per_repeat\",\"internal_repeats\":10,\"component_time_seconds\":[",trial,sum,ok?"true":"false",maxerr);for(int i=0;i<(int)times.size();i++)printf("%s%.12g",i?",":"",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"shape\":[%zu],\"byte_order\":\"little\"}}\n",path.c_str(),prefix.size()+out.size(),prefix.size()+out.size());}}
